import { createOtaHandler } from "denext/server";

const ota = createOtaHandler({ dir: "out", basePath: "/mobile-ui", cors: true });
Deno.serve(async (req) => {
  if (new URL(req.url).pathname.startsWith("/mobile-ui/")) {
